<script setup lang="ts">
import { ref } from 'vue'; import { Link, useForm, router } from '@inertiajs/vue3';
import BaseLayout from '../../layouts/BaseLayout.vue'; import BaseCard from '../../components/BaseCard.vue'; import BaseButton from '../../components/BaseButton.vue'; import ImportReport, { type ImportSummary, type ImportAnomaly } from '../../components/ImportReport.vue';
interface Preview { id: string; event_id: string; filename: string; create_hosts: boolean; summary: ImportSummary; anomalies: ImportAnomaly[]; sample: { line: number; full_name: string; category: string }[] }
const props=defineProps<{ events: { id: string; name: string }[]; selectedEvent: string | null; preview: Preview | null; result: (ImportSummary & { id: string }) | null; results: { id: string; full_name: string; category: { name: string } }[] }>();
const form=useForm<{ event_id: string; file: File | null; create_hosts: boolean }>({ event_id: props.selectedEvent || props.events[0]?.id || '', file: null, create_hosts: props.preview?.create_hosts || false });
const confirmation=useForm({event_id: props.preview?.event_id || '',id:props.preview?.id || ''});const review=ref(false);const query=ref('');
function send() { form.post('/administration/imports/apercu',{forceFormData:true,onSuccess:()=>{review.value=false;confirmation.event_id=props.preview?.event_id||'';confirmation.id=props.preview?.id||'';}}); }
function confirm() { confirmation.event_id=props.preview?.event_id||'';confirmation.id=props.preview?.id||'';confirmation.post('/administration/imports/confirmer',{onSuccess:()=>{review.value=false;}}); }
function abandon() { confirmation.event_id=props.preview?.event_id||'';confirmation.id=props.preview?.id||'';confirmation.post('/administration/imports/abandonner'); }
function search() { router.get('/administration/imports',{event_id:form.event_id,q:query.value},{preserveState:true}); }
</script>
<template>
<BaseLayout>
<Link href="/espace" class="block min-h-14 underline">Mon espace</Link><h1 class="mb-4 text-display font-bold">Administration · Importer une liste</h1><ol class="mb-6 flex flex-wrap gap-4" aria-label="Étapes"><li>1. Choisir le fichier</li><li>2. Vérifier</li><li>3. Confirmer</li></ol><div class="space-y-6">
<BaseCard v-if="!review"><h2 class="mb-4 text-heading font-bold">1. Choisir l’événement et le fichier</h2><p class="mb-4">CSV UTF-8 ou XLSX (première feuille), 5 Mo et 5 000 lignes maximum. Dates : AAAA-MM-JJ (heure facultative HH:MM), en UTC. Sans dates, la période de l’événement est utilisée.</p><a href="/administration/imports/modele" class="action mb-4 inline-flex">Télécharger le modèle CSV</a><form aria-label="Choisir le fichier" class="space-y-4" @submit.prevent="send"><label class="block">Événement<select v-model="form.event_id" class="mt-2 block min-h-14 w-full rounded border p-3" required><option v-for="event in events" :key="event.id" :value="event.id">{{ event.name }}</option></select></label><label class="block">Fichier de visiteurs<input class="mt-2 block min-h-14 w-full" type="file" accept=".csv,.xlsx" required @change="form.file=($event.target as HTMLInputElement).files?.[0] || null" /></label><label class="flex min-h-14 items-center gap-3"><input v-model="form.create_hosts" type="checkbox" class="h-6 w-6" />Créer les hôtes manquants</label><p>Sans cette option, un hôte inconnu bloque sa ligne. Nom complet et catégorie sont obligatoires.</p><p v-for="(error,key) in form.errors" :key="key" role="alert" class="font-bold text-danger">{{ error }}</p><BaseButton :disabled="form.processing || !events.length">{{ form.processing ? 'Contrôle en cours…' : preview ? 'Contrôler le fichier corrigé' : 'Vérifier le fichier' }}</BaseButton></form></BaseCard>
<BaseCard v-if="preview && !review"><h2 class="mb-4 text-heading font-bold">2. Vérifier l’aperçu</h2><p>{{ preview.filename }} · Aucun visiteur enregistré à ce stade.</p><ImportReport :summary="preview.summary" :anomalies="preview.anomalies" /><h3 class="mt-6 font-bold">Aperçu des dix premières lignes importables</h3><ul class="my-4"><li v-for="row in preview.sample" :key="row.line">Ligne {{ row.line }} · {{ row.full_name }} · {{ row.category }}</li></ul><p class="mb-4">Pour corriger, rechargez votre fichier ci-dessus. Le rapport actuel reste disponible si le nouveau fichier est refusé.</p><BaseButton :disabled="!preview.summary.importable" @click="review=true">Continuer vers la confirmation</BaseButton><button class="action ml-3" :disabled="confirmation.processing" @click="abandon">Abandonner et supprimer le fichier</button></BaseCard>
<BaseCard v-if="preview && review"><h2 class="mb-4 text-heading font-bold">3. Confirmer l’import</h2><p class="mb-4">Vous allez ajouter {{ preview.summary.importable }} visiteurs. {{ preview.summary.blocked }} lignes resteront exclues. {{ preview.summary.warnings }} homonymes seront importés avec un avertissement dans le rapport.</p><p class="mb-4">Le fichier privé sera supprimé après l’import. Les visiteurs seront au statut « attendu ».</p><p v-for="(error,key) in confirmation.errors" :key="key" role="alert">{{ error }}</p><BaseButton :disabled="confirmation.processing" @click="confirm">{{ confirmation.processing ? 'Import en cours…' : 'Importer les lignes valides' }}</BaseButton><button class="action ml-3" :disabled="confirmation.processing" @click="review=false">Revenir au rapport</button></BaseCard>
<BaseCard v-if="result"><h2 class="text-heading font-bold">✓ Import terminé</h2><p>{{ result.importable }} visiteurs ajoutés ; {{ result.blocked }} lignes exclues ; {{ result.warnings }} homonymes signalés. Le fichier d’aperçu a été supprimé.</p></BaseCard>
<BaseCard v-if="!preview && selectedEvent"><h2 class="mb-4 text-heading font-bold">Retrouver un visiteur</h2><form class="space-y-4" @submit.prevent="search"><label class="block">Nom à rechercher<input v-model="query" class="block min-h-14 w-full rounded border p-3" minlength="2" maxlength="160" /></label><BaseButton>Rechercher</BaseButton></form><ul class="mt-4"><li v-for="v in results" :key="v.id">{{ v.full_name }} · {{ v.category.name }}</li></ul></BaseCard>
</div>
</BaseLayout>
</template>
